{
  "case_id": "C09",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "Hook",
      "narration": "\"Cuts your risk by 42 percent.\" That sounds huge. But 42 percent of what? Here's a trial that shows why the answer matters.",
      "on_screen": "Bold text: \"42% RISK REDUCTION\" — then a question mark grows beside it.",
      "claim_refs": ["SYN-C09:Results:relative_risk_reduction", "SYN-C09:Background"]
    },
    {
      "beat": "The trial",
      "narration": "Researchers randomly assigned 9,842 adults aged 45 to 70 to either a statin or a dummy pill, and followed them for about four years. None had heart disease or diabetes to begin with, so their baseline risk was low.",
      "on_screen": "Two columns of figures splitting from one group: 4,921 statin / 4,921 placebo. Caption: randomised, blinded, 4.1 years.",
      "claim_refs": ["SYN-C09:Abstract", "SYN-C09:Population", "SYN-C09:Methods"]
    },
    {
      "beat": "The same result, two ways",
      "narration": "On placebo, 4.25 percent had a major cardiovascular event. On the statin, 2.46 percent did. Compare those two as a ratio and you get that 42 percent drop. Subtract them instead, and the difference is 1.79 percentage points.",
      "on_screen": "Side-by-side bars: 4.25% vs 2.46%. Two labels appear: \"42% relative\" and \"1.79 points absolute\".",
      "claim_refs": ["SYN-C09:Results:events", "SYN-C09:Results:relative_risk_reduction", "SYN-C09:Results:absolute_risk_reduction"]
    },
    {
      "beat": "What it means per person",
      "narration": "In everyday terms: about 56 people at this low risk level took a statin for four years to prevent one event. Same trial, same data, two very different-sounding sentences.",
      "on_screen": "Grid of 56 person icons; one turns a highlight colour. Caption: 1 event prevented over 4.1 years.",
      "claim_refs": ["SYN-C09:Results:number_needed_to_treat"]
    },
    {
      "beat": "Takeaway",
      "narration": "Neither number is a trick. Relative risk tells you how well a drug works; absolute risk tells you what it's worth to you, and that depends on how high your risk was to start with. So ask for both.",
      "on_screen": "Two cards side by side: \"Relative: how well it works\" and \"Absolute: what it means for me\".",
      "claim_refs": ["SYN-C09:Discussion", "SYN-C09:Background"]
    }
  ]
}
